No framework named, so vanilla JS. Debounce 300 ms, and abort the in-flight request so a stale response can't overwrite a newer one.

```js
function debounce(fn, delay = 300) {
  let timer;
  return (...args) => {
    clearTimeout(timer);
    timer = setTimeout(() => fn(...args), delay);
  };
}

const input = document.querySelector('#search');
let controller;

async function search(query) {
  controller?.abort();
  if (!query.trim()) return renderResults([]);

  controller = new AbortController();
  try {
    const res = await fetch(`/api/search?q=${encodeURIComponent(query)}`, {
      signal: controller.signal,
    });
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    renderResults(await res.json());
  } catch (err) {
    if (err.name !== 'AbortError') console.error(err);
  }
}

input.addEventListener('input', debounce((e) => search(e.target.value), 300));
```

Swap `#search`, `/api/search?q=` and `renderResults` for your own names.
